def find_by_domain(domain: str) -> list[dict]:
    """Return users whose email is at exactly ``domain`` (case-insensitive), ordered by id."""
    rows = _conn.execute(
        "SELECT id, name, email FROM users "
        "WHERE lower(substr(email, instr(email, '@') + 1)) = lower(?) "
        "ORDER BY id",
        (domain,),
    ).fetchall()
    return [dict(row) for row in rows]

